using System;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using D=System.Collections.Generic.Dictionary<string,object>;
namespace OreumMok {partial class MainForm {
readonly List<Form> workspaces=new List<Form>();
internal void ValidateWorkspaces(string dir){var design=new StairDesignForm(b,J.Clone(state),null,WorkspaceCommit("designs",null));OpenWorkspace(design);ShowPage("lighting");var light=new EditForm("조명 시공 · 동시 작업 검증",J.Row("id",Guid.NewGuid().ToString(),"name","QA lighting"),new[]{new Field("name","공사명"),new Field("fixture","등기구 규격"),new Field("quantity","수량","number")},state,q=>false);OpenWorkspace(light);ShowPage("customers");System.Windows.Forms.Application.DoEvents();if(!Enabled||design.Modal||light.Modal||!design.Visible||!light.Visible)throw new Exception("Modeless workspace validation failed");using(var bitmap=new System.Drawing.Bitmap(Width,Height)){DrawToBitmap(bitmap,new System.Drawing.Rectangle(0,0,Width,Height));bitmap.Save(System.IO.Path.Combine(dir,"native-modeless-main.png"));}light.Close();design.Close();ShowPage("lighting");using(var bitmap=new System.Drawing.Bitmap(Width,Height)){DrawToBitmap(bitmap,new System.Drawing.Rectangle(0,0,Width,Height));bitmap.Save(System.IO.Path.Combine(dir,"native-lighting.png"));}System.IO.File.WriteAllText(System.IO.Path.Combine(dir,"workspace-test.json"),"{\"mainEnabledWithTwoEditors\":true,\"modeless\":true,\"lightingMenu\":true}");}
internal void OpenWorkspace(Form form){form.ShowInTaskbar=true;form.StartPosition=FormStartPosition.CenterParent;workspaces.Add(form);form.FormClosed+=(s,e)=>{workspaces.Remove(form);form.Dispose();};form.Show(this);}
Func<D,bool> WorkspaceCommit(string group,D original){D baseline=original==null?null:J.Clone(original);return row=>{try{D loaded=b.Call("load"),latest=J.Obj(loaded["state"]);D live=J.Rows(latest,group).FirstOrDefault(x=>J.Text(x,"id")==J.Text(row,"id"));if(J.S.Serialize(live)!=J.S.Serialize(baseline)){MessageBox.Show("이 항목은 다른 창 또는 기기에서 변경·삭제됐습니다. 현재 입력은 유지됩니다. 최신 항목을 다시 열어 비교하세요.","동시 편집 확인");return false;}state=latest;version=J.Text(loaded,"version");if(!Store(group,row))return false;baseline=J.Clone(J.Rows(state,group).First(x=>J.Text(x,"id")==J.Text(row,"id")));return true;}catch(Exception ex){MessageBox.Show(ex.Message,"저장 확인");return false;}};}
}}
